/* Validación individual de preguntas importadas, contrastada con guías. Los estados discutibles quedan sin puntuación. */
Object.assign(KEY["pdf-novas-1"]["1"],{"a":"A","status":"validado","why":"El dolor abdominal súbito intenso desproporcionado al examen, con lactato elevado, acidosis y vasculopatía, obliga a descartar de urgencia isquemia mesentérica aguda con angio-TC y valoración quirúrgica.","o":{"B":"La pancreatitis suele acompañarse de elevación de lipasa y dolor epigástrico característico.","C":"La colitis isquémica suele presentar dolor y hematoquecia; no es la presentación más preocupante aquí.","D":"La apendicitis se localiza habitualmente en fosa ilíaca derecha, con signos locales progresivos."},"src":"World Society of Emergency Surgery, Acute Mesenteric Ischemia 2022","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9580452/"});
Object.assign(KEY["pdf-novas-1"]["2"],{"a":"A","status":"validado","why":"La imagen compatible con coledocolitiasis distal sintomática después de colecistectomía orienta a extracción por CPRE con eventual esfinterotomía; no precisa reabrir el abdomen de primera intención.","o":{"B":"La exploración quirúrgica del colédoco se reserva para determinadas circunstancias o fracaso endoscópico.","C":"La extracción mediante tubo de Kehr exige que el paciente tenga ese drenaje, ausente en el caso.","D":"Una anastomosis biliodigestiva abierta no es primera elección para un cálculo distal común."},"src":"NICE, Gallstone disease: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"});
Object.assign(KEY["pdf-novas-1"]["3"],{"a":"C","status":"validado","why":"El adenocarcinoma resecable de cabeza pancreática se trata habitualmente con duodenopancreatectomía cefálica (Whipple) y linfadenectomía regional, dentro de un plan oncológico multidisciplinario.","o":{"A":"La enucleación no es una resección oncológica suficiente de un adenocarcinoma.","B":"La pancreaticoyeyunostomía es parte de la reconstrucción, no la resección tumoral.","D":"La pancreatectomía distal se utiliza para tumores del cuerpo o cola pancreáticos."},"src":"NCI, Pancreatic Cancer Treatment (PDQ)","src_url":"https://www.cancer.gov/types/pancreatic/hp/pancreatic-treatment-pdq"});
Object.assign(KEY["pdf-novas-1"]["4"],{"a":"D","status":"discutible","why":"Fiebre persistente y oliguria tras cirugía abdominal con anastomosis hacen sospechar complicación séptica intraabdominal, incluida fuga anastomótica, pero no permiten confirmar D ni descartar colección/absceso sin exploración, TC y evaluación de sepsis. La cronología del enunciado es internamente confusa.","o":{"A":"Peritonitis posoperatoria también es posible y puede ser consecuencia de una fuga.","B":"Endocarditis no es la primera explicación, salvo signos o bacteriemia específicos.","C":"La sepsis postesplenectomía existe, pero el foco abdominal temprano debe ser investigado."},"src":"WHO Global Guidelines for Prevention of Surgical Site Infection","src_url":"https://www.who.int/publications/i/item/9789241550475"});
Object.assign(KEY["pdf-novas-1"]["5"],{"a":"C","status":"validado","why":"La infiltración preincisional de anestésico local busca disminuir la nocicepción perioperatoria y el dolor posoperatorio como parte de analgesia multimodal; el beneficio depende de técnica y contexto.","o":{"A":"La hemostasia no es el objetivo principal del anestésico local sin vasoconstrictor.","B":"La infiltración no se indica principalmente para facilitar la disección anatómica.","D":"Puede mitigar respuesta simpática, pero la finalidad primaria es analgesia."},"src":"WHO Global Guidelines for Prevention of Surgical Site Infection","src_url":"https://www.who.int/publications/i/item/9789241550475"});
Object.assign(KEY["pdf-novas-1"]["6"],{"a":"C","status":"validado","why":"Masa dolorosa por debajo del ligamento inguinal en una mujer mayor es muy sugestiva de hernia femoral o crural, con riesgo importante de estrangulación y valoración quirúrgica urgente.","o":{"A":"La hernia inguinal directa emerge por encima del ligamento inguinal.","B":"La hernia inguinal indirecta también aparece por encima del ligamento, siguiendo canal inguinal.","D":"La hernia obturatriz suele ser profunda y difícil de palpar como masa femoral superficial."},"src":"NICE, Gallstone disease: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"});
Object.assign(KEY["pdf-novas-1"]["7"],{"a":"D","status":"discutible","why":"Picos febriles y leucocitosis después de cirugía por apendicitis orientan a absceso intraabdominal posoperatorio; la localización subfrénica no se puede inferir sin imágenes. Además la cronología de la cirugía, alta y fiebre se contradice. Requiere TC abdominal para identificar el foco.","o":{"A":"Sinusitis aguda no explica de modo convincente el contexto posoperatorio abdominal.","B":"Peritonitis difusa suele dar mayor irritación peritoneal y deterioro, pero no queda excluida.","C":"Pielonefritis requiere correlación urinaria y examen para justificar su prioridad."},"src":"WHO Global Guidelines for Prevention of Surgical Site Infection","src_url":"https://www.who.int/publications/i/item/9789241550475"});
Object.assign(KEY["pdf-novas-1"]["8"],{"a":"B","status":"validado","why":"En colelitiasis incidental sin cólico biliar ni complicación, la conducta habitual es expectante; la distensión posprandial inespecífica no demuestra cólico biliar.","o":{"A":"No hay indicación de colecistectomía urgente por distensión aislada.","C":"La técnica abierta no previene por sí misma cáncer vesicular; no está indicada profilaxis universal.","D":"El sexo femenino por sí solo no indica colecistectomía profiláctica."},"src":"NICE, Gallstone disease: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"});
Object.assign(KEY["pdf-novas-1"]["9"],{"a":"C","status":"validado","why":"La clasificación ASA V corresponde a paciente moribundo que no se espera que sobreviva sin la operación; no equivale simplemente a enfermedad sistémica grave.","o":{"A":"ASA V no representa riesgo leve.","B":"La enfermedad sistémica grave corresponde a ASA III; si constituye amenaza constante para la vida, ASA IV.","D":"La relación de la enfermedad con la patología quirúrgica no define por sí sola ASA V."},"src":"American Society of Anesthesiologists, ASA Physical Status","src_url":"https://doi.org/10.1097/ao9.0000000000000002"});
Object.assign(KEY["pdf-novas-2"]["1"],{"a":null,"status":"discutible","why":"GABARITO ORIGINAL D NO VÁLIDO: HBsAg positivo y anti-HBs negativo indican infección por VHB, pero no permiten diferenciar infección aguda de crónica sin IgM anti-HBc, cronología y/o persistencia de HBsAg durante 6 meses. HBcAg no es el marcador sérico que sustituye anti-HBc. No hay opción única entre A y D.","o":{"A":"La hepatitis B crónica es posible si HBsAg persiste al menos seis meses.","B":"Hepatitis fulminante requiere evidencia de falla hepática aguda, no suministrada.","C":"La inmunidad por vacuna se caracteriza por anti-HBs positivo aislado.","D":"Hepatitis B aguda es posible, pero requiere IgM anti-HBc y evolución clínica."},"src":"CDC, Clinical Testing and Diagnosis for Hepatitis B","src_url":"https://www.cdc.gov/hepatitis-b/hcp/diagnosis-testing/"});
Object.assign(KEY["pdf-novas-2"]["2"],{"a":"C","status":"validado","why":"CORRECCIÓN DE CLAVE D → C: alteración del estado mental está reconocida entre factores que predicen evolución desfavorable de pancreatitis aguda (BISAP). Los puntos de corte de las otras opciones son inadecuados: edad de riesgo >55 y obesidad IMC >30; Hto elevado clínicamente significativo no se define por >35%.","o":{"A":"Hematocrito de 35% no es marcador de hemoconcentración pronóstica.","B":"IMC apenas >25 no corresponde a obesidad y no es umbral de riesgo de guías.","D":"La edad >40 aislada no es el umbral de predicción habitual (se usa >55 o >60 según escala)."},"src":"ACG, Management of Acute Pancreatitis 2024","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13221274/"});
Object.assign(KEY["pdf-novas-2"]["3"],{"a":"A","status":"validado","why":"El dolor epigástrico súbito con peritonismo e historia de AINE sugiere perforación de úlcera péptica. Una radiografía de tórax en bipedestación puede evidenciar neumoperitoneo; la TC tiene mejor sensibilidad cuando el paciente está estable. Inestabilidad y peritonismo requieren cirugía urgente sin demorar por pruebas.","o":{"B":"El hematocrito no confirma perforación de víscera hueca.","C":"Leucocitosis es inespecífica y no localiza perforación.","D":"La ecografía tiene menor utilidad para detectar aire libre frente a radiografía/TC."},"src":"WSES Guidelines, Perforated and Bleeding Peptic Ulcer","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6947898/"});
Object.assign(KEY["pdf-novas-2"]["4"],{"a":"A","status":"discutible","why":"GABARITO PDF A DUDOSO: consumo elevado de alcohol, hepatomegalia e ictericia obligan a evaluar hepatopatía; sin embargo ALT/TGP 240 es mayor que AST/TGO 125, patrón no típico de hepatitis asociada al alcohol (habitualmente AST/ALT >1,5). Se deben investigar hepatitis viral, medicamentosa, obstrucción y otras causas. No se confirma etiología solo con lo aportado.","o":{"B":"Cirrosis avanzada no puede establecerse por estos datos sin evaluación de función hepática, fibrosis e imagen.","C":"Insuficiencia hepática severa requiere coagulopatía y otros criterios de fallo, no informados.","D":"Hepatitis viral es diagnóstico diferencial importante por patrón hepatocelular; requiere serologías."},"src":"ACG, Management of Acute Pancreatitis 2024","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13221274/"});
Object.assign(KEY["pdf-novas-2"]["5"],{"a":"B","status":"discutible","why":"Paciente internado con distensión colónica generalizada sugiere pseudoobstrucción colónica aguda (Ogilvie). Primero se descarta obstrucción mecánica, isquemia/perforación, se corrigen electrolitos y fármacos y se aplica descompresión conservadora. Neostigmina o colonoscopia se reservan para fracaso del manejo inicial, dilatación importante o curso prolongado. Falta diámetro cecal y tratamientos ya realizados.","o":{"A":"Cecostomía es excepcional y más invasiva, no el primer abordaje rutinario.","C":"Laparotomía se reserva para isquemia, perforación o fracaso de medidas no quirúrgicas.","D":"Hemicolectomía no se indica en pseudoobstrucción simple sin daño intestinal."},"src":"ASGE, acute colonic pseudo-obstruction 2020","src_url":"https://www.asge.org/home/resources/publications/guidelines/american-society-for-gastrointestinal-endoscopy-guideline-on-the-role-of-endoscopy-in-the-management-of-acute-colonic-pseudo-obstruction-and-colonic-volvulus"});
Object.assign(KEY["pdf-novas-2"]["6"],{"a":"B","status":"validado","why":"Paciente con cáncer avanzado y uso de morfina: estreñimiento relacionado con opioides sin signos de obstrucción. Se evalúa fecaloma mediante tacto rectal y se comienza laxante osmótico o estimulante según clínica; corregir el error tipográfico «impactación fetal» por «impactación fecal».","o":{"A":"Reducir el opioide a la mitad puede descontrolar el dolor y no es primera elección.","C":"Un procinético gástrico no sustituye los laxantes indicados para estreñimiento por opioides.","D":"Sin vómitos, abdomen patológico ni alarma no hay indicación automática de TC urgente."},"src":"American Gastroenterological Association, Constipation medical position statement","src_url":"https://gastrojournal.org/article/S0016-5085(12)01056-2/fulltext"});
Object.assign(KEY["pdf-novas-2"]["7"],{"a":"A","status":"validado","why":"En el sobrecrecimiento bacteriano del intestino delgado, las pruebas diagnósticas habituales son tests de aliento o aspirado/cultivo intestinal en casos seleccionados; la biopsia no constituye la prueba diagnóstica de rutina.","o":{"B":"Puede existir anemia por malabsorción de vitamina B12 o nutrientes.","C":"Cirugía digestiva previa favorece estasis y sobrecrecimiento.","D":"Diarrea, distensión y malabsorción son presentaciones reconocidas."},"src":"ACG Clinical Guideline, Small Intestinal Bacterial Overgrowth","src_url":"https://pubmed.ncbi.nlm.nih.gov/32023228/"});
Object.assign(KEY["pdf-novas-2"]["8"],{"a":"D","status":"validado","why":"Varón joven atópico con episodios de impactación alimentaria y disfagia es sugestivo de esofagitis eosinofílica; se confirma con endoscopia y biopsias. Incapacidad para tragar saliva exige endoscopia urgente por obstrucción esofágica completa.","o":{"A":"El esófago de Barrett se relaciona con reflujo crónico y no es causa típica de impactación en joven atópico.","B":"El anillo de Schatzki causa disfagia intermitente a sólidos, pero la fuerte atopia orienta más a EoE.","C":"La esofagitis infecciosa suele cursar con odinofagia y en inmunodepresión."},"src":"ACG Clinical Guideline, Eosinophilic Esophagitis","src_url":"https://pubmed.ncbi.nlm.nih.gov/39745304/"});
Object.assign(KEY["pdf-novas-2"]["9"],{"a":"C","status":"validado","why":"Úlcera en cara posterior de bulbo duodenal puede erosionar arteria gastroduodenal. Forrest Ib (sangrado en napa) tiene riesgo de resangrado y requiere hemostasia eficaz; adrenalina endoscópica como único método NO es suficiente según guías actuales, debe combinarse con clip o terapia térmica.","o":{"A":"Forrest Ib implica sangrado activo y riesgo de recidiva no bajo.","B":"Ante resangrado es posible segundo tratamiento endoscópico; la cirugía no es obligatoria de entrada.","D":"La vagotomía troncular ya no es procedimiento universal obligatorio ante sangrado ulceroso."},"src":"ACG, Upper Gastrointestinal and Ulcer Bleeding 2021","src_url":"https://pubmed.ncbi.nlm.nih.gov/33929377/"});
Object.assign(KEY["pdf-novas-2"]["10"],{"a":"A","status":"validado","why":"El déficit de B12 por gastritis autoinmunitaria del cuerpo gástrico se asocia con atrofia oxíntica, metaplasia intestinal e hiperplasia de células enterocromafines; H. pylori no es hallazgo morfológico necesario o característico en la biopsia corporal, aunque infección concomitante puede existir.","o":{"B":"La metaplasia intestinal puede observarse en la gastritis atrófica crónica.","C":"La hiperplasia de células neuroendocrinas ECL es típica por hipergastrinemia.","D":"La atrofia de glándulas oxínticas es el sustrato clásico de anemia perniciosa."},"src":"ACG/CAG Clinical Practice Guidelines on the Management of Dyspepsia","src_url":"https://pubmed.ncbi.nlm.nih.gov/28631728/"});
Object.assign(KEY["pdf-novas-2"]["11"],{"a":"D","status":"validado","why":"Anemia ferropénica severa en mujer posmenopáusica obliga a investigar pérdida digestiva, especialmente colon, aunque endoscopia alta encuentre hernia hiatal pequeña sin esofagitis. La videocolonoscopia es el paso clave para descartar lesión colorrectal.","o":{"A":"Hierro oral trata el déficit, pero sin investigar causa digestiva de anemia en posmenopausia es insuficiente.","B":"IBP para pirosis no resuelve la etiología de la anemia.","C":"La cápsula endoscópica se considera posteriormente si endoscopia alta y colonoscopia no explican la anemia."},"src":"ACG, Upper Gastrointestinal and Ulcer Bleeding 2021","src_url":"https://pubmed.ncbi.nlm.nih.gov/33929377/"});
Object.assign(KEY["pdf-novas-2"]["12"],{"a":"C","status":"validado","why":"La mayoría de pacientes con síntomas dispépticos no tienen úlcera u otra lesión estructural y cumplen criterios de dispepsia funcional; requiere excluir signos de alarma y seguir evaluación acorde con edad.","o":{"A":"Alcohol puede agravar síntomas pero no es la etiología principal global.","B":"La úlcera péptica es causa orgánica, proporcionalmente menos frecuente.","D":"AINE favorece gastritis/úlcera pero no explica la mayoría de dispepsias."},"src":"ACG/CAG Clinical Practice Guidelines on the Management of Dyspepsia","src_url":"https://pubmed.ncbi.nlm.nih.gov/28631728/"});
Object.assign(KEY["pdf-novas-2"]["13"],{"a":"D","status":"validado","why":"Polietilenglicol (PEG o macrogol) retiene agua por efecto osmótico en el lumen intestinal, ablandando heces y facilitando su eliminación.","o":{"A":"No aumenta masa por fibras fermentables como psyllium.","B":"No es laxante estimulante directo del peristaltismo como bisacodilo.","C":"No actúa recubriendo o lubricando heces como aceite mineral."},"src":"American Gastroenterological Association, Constipation medical position statement","src_url":"https://gastrojournal.org/article/S0016-5085(12)01056-2/fulltext"});
Object.assign(KEY["pdf-novas-3"]["1"],{"a":"A","status":"validado","why":"Ante sospecha de fractura de base de cráneo o trauma mediofacial importante, debe evitarse paso ciego de sonda por vía nasal por riesgo de colocación intracraneal. Preferir vía orogástrica si está indicada.","o":{"B":"Fracturas orbitales/mandibulares aisladas no equivalen siempre a fractura de base; valorar anatomía y lesiones específicas.","C":"Epistaxis es precaución y puede impedir el procedimiento, pero el principal criterio anatómico absoluto ofrecido es fractura de base.","D":"Fractura de suelo orbitario aislada no define la misma contraindicación anatómica."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});
Object.assign(KEY["pdf-novas-3"]["2"],{"a":"D","status":"discutible","why":"La conducta inicial depende del tipo, ubicación y síntomas del cuerpo extraño. Radiografía de cuello/tórax sirve si es radiopaco o desconocido; batería botón, objeto punzante u obstrucción esofágica completa requieren endoscopia urgente, sin demoras. Faltan esos datos para seleccionar universalmente D frente a C.","o":{"A":"Dar grandes cantidades de agua puede agravar obstrucción o aspiración.","B":"Espasmolíticos no son medida inicial indicada para cuerpo extraño esofágico.","C":"La esofagoscopia es prioritaria si existe obstrucción completa, pila botón o objeto punzante; no universal en todos los casos."},"src":"ASGE, ingested foreign bodies and food impactions","src_url":"https://www.asge.org/home/resources/publications/guidelines/management-of-ingested-foreign-bodies-and-food-impactions"});
Object.assign(KEY["pdf-novas-3"]["3"],{"a":"D","status":"validado","why":"La secuencia propuesta más cercana a la cadena de supervivencia es reconocimiento de paro y activación de emergencias, RCP precoz, desfibrilación temprana, atención avanzada y cuidados posresucitación. La opción D simplifica la cadena, pero respeta el orden fundamental.","o":{"A":"Anteponer desfibrilación al pedido de ayuda y reconocimiento del paro omite la secuencia inicial.","B":"Abrir vía aérea antes de activar servicios y no iniciar RCP omite un eslabón esencial.","C":"Demorar reconocimiento/solicitud de ayuda y desfibrilación reduce posibilidades de supervivencia."},"src":"American Heart Association, Adult BLS 2025","src_url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support/"});
Object.assign(KEY["pdf-novas-3"]["4"],{"a":"A","status":"validado","why":"Traumatismo abdominal cerrado con hipotensión y taquicardia, palidez y diaforesis sugiere hemorragia interna y choque hipovolémico hemorrágico hasta demostrar lo contrario.","o":{"B":"No hay foco infeccioso ni evolución para choque séptico.","C":"Choque cardiogénico implica falla de bomba y no es la principal hipótesis tras trauma abdominal.","D":"Choque neurogénico suele asociarse a lesión medular y puede producir bradicardia relativa."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});
Object.assign(KEY["pdf-novas-3"]["5"],{"a":"B","status":"validado","why":"Quemadura dérmica superficial de espesor parcial o segundo grado puede ser muy dolorosa, con ampollas y superficie húmeda/exudativa; profundidad y sensibilidad cambian si la lesión es más profunda.","o":{"A":"Superficie muy dura y seca sugiere quemadura más profunda, no patrón superficial típico.","C":"Dolor escaso o ausente orienta a lesión de espesor completo o profunda.","D":"Eritema sin ampollas es más típico de lesión superficial de primer grado."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});
Object.assign(KEY["pdf-novas-3"]["6"],{"a":"B","status":"validado","why":"Compresiones de RCP del adulto a 100–120 por minuto, con profundidad de 5–6 cm, descompresión completa y mínimas interrupciones, según recomendaciones AHA 2025.","o":{"A":"100–150 incluye frecuencias excesivas por encima del límite superior recomendado.","C":"80–100 queda por debajo del rango recomendado en buena parte del intervalo.","D":"60–100 también es demasiado lento para RCP de alta calidad."},"src":"American Heart Association, Adult BLS 2025","src_url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support/"});
Object.assign(KEY["pdf-novas-3"]["7"],{"a":"C","status":"validado","why":"La evaluación primaria del trauma sigue ABCDE: A vía aérea con protección cervical, B ventilación, C circulación y control de hemorragia, D discapacidad neurológica, E exposición y prevención de hipotermia.","o":{"A":"Prioriza circulación antes de respiración, alterando el ABCDE.","B":"Prioriza respiración antes de vía aérea y su protección cervical.","D":"Inicia por respiración/exposición sin asegurar vía aérea o controlar secuencia ABCDE."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});

/* Validación científica individual: ginecología y hematología */
Object.assign(KEY["pdf-novas-4"]["1"],{"a":"A","status":"validado","why":"En preeclampsia, plaquetas inferiores a 100.000/µL representan compromiso hematológico grave, incluso sin hipertensión extrema. Las demás opciones aisladas no son criterios de severidad.","o":{"B":"El edema periférico es inespecífico y muy frecuente en gestación.","C":"Proteinuria 1+ aislada no define severidad ni constituye cuantificación adecuada.","D":"Presión arterial 140/90 señala hipertensión, pero no hipertensión de rango grave (≥160/110)."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["2"],{"a":"B","status":"discutible","why":"El caso sugiere síndrome de ovario poliquístico por oligomenorrea, acné y sobrepeso, pero en mujeres adultas con ciclos irregulares e hiperandrogenismo clínico la ecografía NO es obligatoria para establecer diagnóstico; también deben excluirse otras causas (TSH, prolactina, 17-OHP según contexto). Por eso la afirmación de que ecografía transvaginal es estudio de mayor valor no es universal.","o":{"A":"Ecografía tiroidea no evalúa función tiroidea y no es prueba inicial de SOP.","C":"La determinación de hormonas tiroideas puede ser útil para excluir diagnóstico alternativo, sin confirmar SOP.","D":"La TC abdominal no es método diagnóstico estándar para SOP."},"src":"Guía internacional basada en evidencia para síndrome de ovario poliquístico, 2023","src_url":"https://academic.oup.com/humrep/article/38/9/1655/7241786"});
Object.assign(KEY["pdf-novas-4"]["3"],{"a":"A","status":"validado","why":"Rotura prematura de membranas con fiebre, taquicardia materna, dolor y secreción fétida sugiere infección intraamniótica; se indican antibióticos intravenosos, estabilización y finalización del embarazo. La vía del parto depende de indicaciones obstétricas, no cesárea sistemática.","o":{"B":"Los antibióticos solos sin plan obstétrico no resuelven el foco cuando existe infección intraamniótica.","C":"La observación sin tratamiento expone a sepsis materno-fetal.","D":"La cesárea urgente no es obligatoria por corioamnionitis aislada; valorar condiciones de parto."},"src":"NICE NG25, parto prematuro y rotura prematura de membranas","src_url":"https://www.nice.org.uk/guidance/ng25/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["4"],{"a":"A","status":"validado","why":"Miomas uterinos sintomáticos con sangrado importante y deseo de fertilidad hacen considerar tratamiento conservador del útero; la miomectomía es opción entre las ofrecidas. Valorar localización, distorsión endometrial, síntomas, reserva reproductiva y preferencias.","o":{"B":"La histerectomía elimina la fertilidad y contradice deseo reproductivo.","C":"La embolización puede afectar fertilidad y no es opción preferida en todas las que desean gestación.","D":"Los agonistas GnRH pueden reducir temporalmente volumen/sangrado, pero no son solución definitiva habitual."},"src":"ACOG, Uterine Fibroids","src_url":"https://www.acog.org/womens-health/faqs/uterine-fibroids"});
Object.assign(KEY["pdf-novas-4"]["5"],{"a":"A","status":"validado","why":"La metrorragia posmenopáusica bajo tamoxifeno requiere estudio histológico del endometrio; la histeroscopia con biopsia dirigida es adecuada dada imagen quística/endometrio de 18 mm. No asumir benignidad por tamoxifeno ni decidir solo por grosor.","o":{"B":"Histerectomía total sin diagnóstico histológico previo es excesiva.","C":"El control habitual ignora sangrado posmenopáusico de alarma.","D":"Legrado endocervical aislado no evalúa de manera suficiente cavidad endometrial."},"src":"HSE Clinical Practice Guideline, Postmenopausal Bleeding (incluye tamoxifeno)","src_url":"https://www.hse.ie/eng/about/who/acute-hospitals-division/woman-infants/clinical-guidelines/assessment-and-management-of-postmenopausal-bleeding.pdf"});
Object.assign(KEY["pdf-novas-4"]["6"],{"a":"C","status":"validado","why":"Levetiracetam no induce enzimas hepáticas y por ello tiene menos interacción con anticonceptivos combinados que carbamazepina o fenobarbital. La selección definitiva depende del tipo de epilepsia, potencial de embarazo y asesoramiento preconcepcional.","o":{"A":"Carbamazepina induce enzimas y reduce eficacia de varios anticonceptivos hormonales.","B":"Fenobarbital es un potente inductor enzimático con numerosas interacciones.","D":"Valproato implica riesgos teratogénicos importantes; evitarlo en mujeres con potencial gestacional si alternativas son eficaces."},"src":"American Academy of Neurology, Antiseizure Medications During Pregnancy","src_url":"https://www.aan.com/Guidelines/home/GuidelineDetail/1108"});
Object.assign(KEY["pdf-novas-4"]["7"],{"a":"B","status":"validado","why":"Plaquetas 85.000, transaminasas elevadas y LDH 650 en preeclampsia grave cumplen datos compatibles con síndrome HELLP (hemólisis, enzimas hepáticas altas, plaquetas bajas). Requiere estabilización obstétrica y decisión de finalización del embarazo.","o":{"A":"El diagnóstico de preeclampsia grave es cierto, pero la constelación de laboratorio apunta específicamente a HELLP.","C":"Preeclampsia leve es incompatible con trombocitopenia y citólisis importantes.","D":"No hay datos específicos de síndrome urémico hemolítico; la tríada obstétrica caracteriza HELLP."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["8"],{"a":"D","status":"discutible","why":"La placenta previa y el desprendimiento prematuro de placenta son dos causas importantes de hemorragia en la segunda mitad de la gestación. La expresión «causa patológica más frecuente» depende de población y definición, sin especificarlas; las frecuencias reportadas se solapan. Se conserva D como propuesta histórica, sin nota.","o":{"A":"La rotura uterina es mucho menos frecuente y generalmente tiene factores de riesgo obstétrico.","B":"El desprendimiento prematuro de placenta también es causa relevante y puede ser muy grave.","C":"La rotura de vasa previa es una causa infrecuente de sangrado agudo fetal."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["9"],{"a":"B","status":"discutible","why":"El primer control prenatal incluye VIH, sífilis, hepatitis B, además de Chagas según riesgo epidemiológico y evaluación de toxoplasmosis según protocolo local. Sin embargo varias combinaciones contienen pruebas recomendables y omiten otras; no se especifica jurisdicción ni calendario 2026, por lo que B no representa un panel universal exclusivo.","o":{"A":"La rubéola puede evaluarse según inmunidad y antecedentes, sin sustituir sífilis.","C":"B reúne pruebas relevantes, pero no siempre constituye el panel completo y universal.","D":"La opción C también reúne serologías frecuentes en distintos protocolos, aunque omite Chagas."},"src":"CDC, STI Screening Recommendations during Pregnancy","src_url":"https://www.cdc.gov/std/treatment-guidelines/screening-recommendations.htm"});
Object.assign(KEY["pdf-novas-4"]["10"],{"a":"D","status":"discutible","why":"Las maniobras de Leopold I y II aportan a la identificación de situación fetal. La primera distingue qué polo ocupa el fondo; la segunda palpa dorso y partes pequeñas y ayuda a establecer situación/posición. El enunciado no especifica qué dimensión quiere determinar y D no es inequívoca.","o":{"A":"La tercera maniobra identifica la parte presentada y su movilidad.","B":"La segunda maniobra puede determinar situación y posición fetal mediante palpación del dorso y extremidades.","C":"La cuarta valora encajamiento y actitud de la presentación."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["11"],{"a":"B","status":"discutible","why":"Dolor súbito y sangrado intraparto con antecedente de cesárea hacen sospechar ruptura uterina sobre cicatriz previa, urgencia obstétrica. La opción B dice «dehiscencia» —que puede ser incompleta y paucisintomática—, y no ofrece explícitamente ruptura completa. Es más seguro mantenerla no puntuable y señalar evaluación/cesárea emergente según compromiso.","o":{"A":"Rotura de vasa previa suele manifestarse tras rotura de membranas con sufrimiento fetal.","C":"Dehiscencia cicatricial es la más cercana, pero no debe equipararse a ruptura uterina completa.","D":"Rotura de seno marginal no explica de forma típica el cuadro asociado a cicatriz previa."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["12"],{"a":"B","status":"validado","why":"La detección de fosfatidilglicerol en líquido amniótico es menos interferida por contaminación sanguínea que otras pruebas históricas de madurez pulmonar. Actualmente esas pruebas tienen un papel mucho menor porque las decisiones dependen de edad gestacional y contexto clínico.","o":{"A":"El cociente lecitina/esfingomielina puede afectarse por contaminación de la muestra.","C":"El test de Clements no es fiable en presencia de sangre u otros contaminantes.","D":"La citología del líquido amniótico no es método preferido para valorar madurez surfactante."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["13"],{"a":"D","status":"validado","why":"La ecografía ginecológica transvaginal no constituye cribado rutinario de cáncer de ovario/endometrio en mujer asintomática de riesgo promedio. Los otros estudios pueden estar indicados según edad y esquema nacional (colonoscopia es una modalidad posible de cribado colorrectal, no necesariamente el único método).","o":{"A":"El Papanicolaou puede formar parte de prevención de cáncer cervical según pautas locales.","B":"La colonoscopia es una opción de cribado colorrectal en edades elegibles, aunque pueden usarse tests de heces.","C":"El perfil lipídico se indica según riesgo cardiometabólico; no implica ecografía ginecológica."},"src":"NCI, Cervical Cancer Causes/Risks/Prevention","src_url":"https://www.cancer.gov/types/cervical/causes-risk-prevention"});
Object.assign(KEY["pdf-novas-4"]["14"],{"a":"B","status":"validado","why":"Endometriosis suele manifestarse con dismenorrea, dolor pélvico y subfertilidad/infertilidad, aunque puede ser asintomática o causar dispareunia profunda y síntomas intestinales o urinarios cíclicos.","o":{"A":"La disuria es posible, pero menos característica que dismenorrea y dolor pélvico juntos.","C":"Tenesmo rectal puede ocurrir en enfermedad profunda pero no es síntoma principal general.","D":"Menometrorragia y anemia no constituyen la tríada típica de presentación."},"src":"ACOG, Uterine Fibroids","src_url":"https://www.acog.org/womens-health/faqs/uterine-fibroids"});
Object.assign(KEY["pdf-novas-4"]["15"],{"a":"B","status":"discutible","why":"El tabaquismo en menores de 35 años no se considera categoría 4 para anticonceptivos combinados por sí solo (generalmente categoría 2). Sin embargo la alternativa A mezcla hipertensión moderada (categoría 3) y severa (categoría 4), de modo que A tampoco representa siempre categoría 4. Falta grado de hipertensión y enunciado inequívoco.","o":{"A":"HTA moderada puede ser categoría 3; HTA grave ≥160/100 es categoría 4.","C":"El tabaquismo de cualquier intensidad antes de los 35 años no es automáticamente categoría 4.","D":"La migraña con aura es categoría 4 para anticonceptivos combinados."},"src":"OMS, Medical Eligibility Criteria for Contraceptive Use 2025","src_url":"https://www.ncbi.nlm.nih.gov/books/NBK619474/table/ch5.tab11/"});
Object.assign(KEY["pdf-novas-4"]["16"],{"a":"C","status":"validado","why":"Masa anexial quística compleja de 6 cm con proyección papilar en posmenopáusica exige descartar neoplasia ovárica. Se recomienda valoración especializada/oncoginecológica, caracterización de riesgo y eventual manejo quirúrgico; CA125 complementa pero no confirma diagnóstico.","o":{"A":"La TC por sí sola no sustituye valoración especializada y enfoque quirúrgico cuando la masa es sospechosa.","B":"CA125 y Doppler pueden ampliar estratificación pero no constituyen tratamiento definitivo frente a papila sospechosa.","D":"Esperar tres meses sin evaluación adicional puede retrasar diagnóstico de tumor."},"src":"NCI, Breast Cancer Treatment (PDQ)","src_url":"https://www.cancer.gov/types/breast/hp/breast-treatment-pdq"});
Object.assign(KEY["pdf-novas-4"]["17"],{"a":"B","status":"validado","why":"En muerte fetal retenida puede desarrollarse coagulopatía por consumo/coagulación intravascular diseminada, una complicación materna grave; su riesgo depende del tiempo y causas de óbito, por lo que se evalúan coagulación y fibrinógeno.","o":{"A":"Hemorragia puede complicar el cuadro pero la coagulopatía es complicación sistémica especialmente temida.","C":"Infección puede ocurrir, sin ser la complicación de consumo específica.","D":"Eclampsia no es consecuencia necesaria del óbito fetal aislado."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["18"],{"a":"B","status":"validado","why":"VPH 16 y 18, tipos oncogénicos, causan aproximadamente 70% de los cánceres cervicouterinos a nivel mundial.","o":{"A":"VPH 6 y 11 son de bajo riesgo y se relacionan con verrugas genitales.","C":"VPH 40 y 42 no son los principales tipos carcinogénicos.","D":"VPH 54 y 61 tampoco explican la mayoría de neoplasias cervicales."},"src":"NCI, Cervical Cancer Causes/Risks/Prevention","src_url":"https://www.cancer.gov/types/cervical/causes-risk-prevention"});
Object.assign(KEY["pdf-novas-4"]["19"],{"a":"B","status":"validado","why":"Secreción espontánea, unilateral, por un único conducto y sanguinolenta es patológica; citología negativa tiene sensibilidad insuficiente para descartar cáncer. Corresponde evaluación mamaria dirigida y estudios por imagen, con biopsia según hallazgos.","o":{"A":"Citología negativa no excluye carcinoma ni permite abandonar evaluación.","C":"Citología positiva requiere estudio anatomopatológico y estadificación, no cirugía amplia automática sin contexto.","D":"La radioterapia no se indica por citología positiva del derrame sin diagnóstico y estadificación."},"src":"NCI, Breast Cancer Treatment (PDQ)","src_url":"https://www.cancer.gov/types/breast/hp/breast-treatment-pdq"});
Object.assign(KEY["pdf-novas-4"]["20"],{"a":"A","status":"validado","why":"Los inhibidores de ECA, incluido enalapril, deben suspenderse al confirmarse embarazo por riesgo fetal. Metildopa es alternativa compatible con gestación; según disponibilidad también se utilizan labetalol o nifedipina.","o":{"B":"Continuar enalapril mantiene exposición fetal inapropiada.","C":"Agregar diurético no corrige la contraindicación de enalapril.","D":"No corresponde esperar arbitrariamente TA sistólica >155 para sustituir tratamiento y controlar presión."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["21"],{"a":"B","status":"validado","why":"Antes de iniciar anticonceptivo combinado, medir la presión arterial es un requisito esencial de seguridad. No se requiere rutinariamente PAP, ecografía, laboratorio hepático ni exploración pelviana en mujer sana.","o":{"A":"Papanicolaou y enzimas hepáticas no son condición de inicio del método.","C":"Laboratorio y ecografía vaginal indiscriminados añaden intervenciones sin indicación.","D":"PAP de cribado no debe usarse como barrera a anticoncepción."},"src":"OMS, Medical Eligibility Criteria for Contraceptive Use 2025","src_url":"https://www.ncbi.nlm.nih.gov/books/NBK619474/table/ch5.tab11/"});
Object.assign(KEY["pdf-novas-4"]["22"],{"a":"D","status":"discutible","why":"Cervicitis purulenta en mujer joven con pareja con uretritis precisa NAAT para gonococo/clamidia e inicio empírico oportuno; ceftriaxona y doxiciclina 7 días son preferidos cuando se sospechan ambos. La clave histórica D usa azitromicina en lugar de doxiciclina y depende de pauta vigente y prevalencia; ninguna opción refleja perfectamente conducta actual.","o":{"A":"Metronidazol aislado no trata gonorrea ni clamidia.","B":"Aguardar cultivo antes del tratamiento puede prolongar transmisión y complicaciones.","C":"Internación/ecografía urgente no está justificada sin dolor ni criterios de EPI grave; la combinación ceftriaxona-doxiciclina es apropiada."},"src":"CDC, Urethritis and Cervicitis","src_url":"https://www.cdc.gov/std/treatment-guidelines/urethritis-and-cervicitis.htm"});
Object.assign(KEY["pdf-novas-4"]["23"],{"a":"C","status":"validado","why":"La candidiasis vulvovaginal recurrente en mujer obesa debe motivar evaluación de diabetes o hiperglucemia, por lo que glucemia es el estudio de mayor rendimiento de los propuestos.","o":{"A":"Orina completa no detecta de forma sensible diabetes ni explica recidivas por sí sola.","B":"Hormonas tiroideas no son la primera prueba ante esta sospecha clínica.","D":"Hemograma no caracteriza el factor metabólico predisponente."},"src":"CDC, Vulvovaginal Candidiasis, recurrent infections","src_url":"https://www.cdc.gov/std/treatment-guidelines/candidiasis.htm"});
Object.assign(KEY["pdf-novas-4"]["24"],{"a":"A","status":"validado","why":"Agenesia uterovaginal con ovarios normales, caracteres sexuales femeninos desarrollados y anomalía renal asociada es clásica de síndrome de Mayer-Rokitansky-Küster-Hauser (MRKH).","o":{"B":"La insensibilidad completa a andrógenos presenta cariotipo 46,XY y testículos, no ovarios normales.","C":"Hiperplasia suprarrenal congénita puede causar virilización, no ausencia uterina con ovarios habituales.","D":"SOP no produce agenesia uterovaginal."},"src":"NCI, Cervical Cancer Causes/Risks/Prevention","src_url":"https://www.cancer.gov/types/cervical/causes-risk-prevention"});
Object.assign(KEY["pdf-novas-4"]["25"],{"a":"B","status":"validado","why":"El progestágeno genera endometrio poco receptivo y ESPESA el moco cervical, dificultando paso espermático, además de participar en supresión de ovulación según método.","o":{"A":"La disminución de viscosidad cervical no es efecto anticonceptivo del progestágeno.","C":"No estimula la producción endógena de estrógenos como mecanismo principal.","D":"El aumento de estrógeno endógeno no es mecanismo anticonceptivo de gestágenos."},"src":"OMS, Medical Eligibility Criteria for Contraceptive Use 2025","src_url":"https://www.ncbi.nlm.nih.gov/books/NBK619474/table/ch5.tab11/"});
Object.assign(KEY["pdf-novas-4"]["26"],{"a":null,"status":"discutible","why":"GABARITO ORIGINAL B CLÍNICAMENTE INCORRECTO: cuadro sugerente de enfermedad pélvica inflamatoria requiere antibióticos de amplio espectro, normalmente ceftriaxona más doxiciclina por 14 días más metronidazol 14 días, según situación. Un DIU colocado no debe retirarse de rutina; seguimiento en 48–72 h y considerar retiro si no mejora o la paciente lo desea. La opción B propone retiro obligatorio, no incluye metronidazol y usa doxiciclina 10 días. Ninguna alternativa describe la conducta adecuada.","o":{"A":"Retirar DIU y dar óvulos no trata infección ascendente.","B":"Retiro automático, dosis insuficiente y antibióticos incompletos no siguen guías actuales.","C":"Esperar cultivos antes de antibióticos retrasa tratamiento de EPI.","D":"Analgesia y retiro sin antibióticos no evitan complicaciones ni infertilidad."},"src":"CDC, Pelvic Inflammatory Disease guidelines","src_url":"https://www.cdc.gov/std/treatment-guidelines/pid.htm"});
Object.assign(KEY["pdf-novas-4"]["27"],{"a":"C","status":"discutible","why":"Quiste de 7 cm con ecos finos compatibles con endometrioma y dismenorrea hace razonable considerar laparoscopia terapéutica, pero la conducta depende de síntomas, deseo reproductivo, reserva ovárica, sospecha de malignidad y experiencia quirúrgica. No toda paciente con solo 7 meses de búsqueda requiere cirugía inmediata; la clave C no es universal.","o":{"A":"Anticonceptivos alivian dolor, pero inhiben ovulación durante uso y no satisfacen búsqueda de embarazo activa.","B":"Tratamiento médico aislado puede ser válido para dolor, aunque no elimina el endometrioma.","D":"Laparoscopia puede ser apropiada si síntomas intensos o quiste grande, equilibrando pérdida de reserva ovárica."},"src":"ACOG, Uterine Fibroids","src_url":"https://www.acog.org/womens-health/faqs/uterine-fibroids"});
Object.assign(KEY["pdf-novas-4"]["28"],{"a":"B","status":"validado","why":"pH fetal en sangre de cuero cabelludo de 7,22 cae en intervalo límite/prepatológico (7,21–7,24) de protocolos históricos: repetir muestreo en 15–30 minutos si persiste cardiotocografía preocupante y parto no es inminente. En práctica actual la técnica se usa cada vez menos.","o":{"A":"Acidosis grave suele considerarse pH <7,20 y exige reacción urgente.","C":"No corresponde demorar 1–2 h ante registro preocupante con pH límite.","D":"No hay evidencia de error de muestra solo por valor de 7,22."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["29"],{"a":null,"status":"discutible","why":"PREGUNTA CLÍNICAMENTE PELIGROSA: neonata con signos de sífilis congénita y madre tratada por vía oral (tratamiento inadecuado en embarazo). No se debe esperar fondo oscuro ni VDRL para iniciar tratamiento. El régimen preferido es penicilina G cristalina IV 100.000–150.000 U/kg/día según edad, por 10 días; la dosis fija de 300.000 U/día y duración 10–15 días de C no es pauta segura universal. No hay alternativa correcta.","o":{"A":"Un VDRL no reactivo aislado del neonato no descarta infección congénita.","B":"Un VDRL reactivo aislado tampoco confirma de manera definitiva; penicilina benzatínica 2,4 millones semanal es dosis de adulto, NO de recién nacido.","C":"El fondo oscuro de lesión puede apoyar diagnóstico, pero no debe retrasar penicilina IV ajustada por peso y edad.","D":"La alergia materna no autoriza eritromicina neonatal; penicilina es tratamiento indicado."},"src":"AAP, Congenital Syphilis Evaluation and Treatment","src_url":"https://www.aap.org/en/patient-care/congenital-syphilis/congenital-syphilis-evaluation-and-treatment-guide/"});
Object.assign(KEY["pdf-novas-4"]["30"],{"a":"A","status":"validado","why":"Dolor y sangrado en embarazo precoz con test positivo obligan a localizar la gestación y descartar ectópico mediante ecografía transvaginal, asociando β-hCG cuantitativa y seguimiento según estabilidad.","o":{"B":"Legrado sin definir localización y viabilidad puede dañar embarazo intrauterino deseado.","C":"Progesterona no sustituye estudio de embarazo ectópico.","D":"Prostaglandinas sin confirmar diagnóstico pueden ser perjudiciales."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["31"],{"a":"B","status":"discutible","why":"La irrigación vaginal procede sobre todo de arterias vaginales y ramas cervicovaginales de la uterina, originadas en la circulación ilíaca interna. La redacción de «vésico-vaginal rama de hipogástrica» no es nomenclatura estándar única, aunque B se aproxima al origen interno; ninguna opción reproduce con precisión anatomía variable.","o":{"A":"La rama cervicovaginal no surge normalmente de la hemorroidal media como único tronco.","C":"La arteria vaginal puede nacer de ilíaca interna, de uterina o de otras ramas, no necesariamente una «vésico-vaginal» exclusiva.","D":"La femoral no es origen principal de arteria vaginal."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["32"],{"a":"D","status":"validado","why":"Candidiasis vulvovaginal recurrente (≥3 episodios sintomáticos/año): confirmar diagnóstico/especie, valorar control de diabetes, inducción antifúngica prolongada y mantenimiento con fluconazol oral SEMANAL durante 6 meses si Candida albicans susceptible; D es la que más se aproxima al período recomendado, aunque no explicita la frecuencia oral.","o":{"A":"Un esquema corto de fluconazol sin mantenimiento no previene bien recurrencias.","B":"Tres meses de mantenimiento es inferior a los seis meses recomendados.","C":"Tres meses de terapia oral no es la duración habitual de mantenimiento, aunque inducción local prolongada puede servir."},"src":"CDC, Vulvovaginal Candidiasis, recurrent infections","src_url":"https://www.cdc.gov/std/treatment-guidelines/candidiasis.htm"});
Object.assign(KEY["pdf-novas-5"]["1"],{"a":"C","status":"validado","why":"La deficiencia de folato interfiere con síntesis de ADN y causa anemia megaloblástica de VCM elevado, habitualmente macrocítica.","o":{"A":"Anemia sideroblástica suele tener VCM bajo o dimorfismo, no macrocitosis habitual.","B":"La ferropenia causa anemia microcítica hipocrómica.","D":"Talasemias suelen producir microcitosis desproporcionada."},"src":"Merck Manual Professional, Evaluation of Anemia","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology/approach-to-the-patient-with-anemia/evaluation-of-anemia"});
Object.assign(KEY["pdf-novas-5"]["2"],{"a":"B","status":"validado","why":"La anisocitosis describe variación del tamaño de eritrocitos, reflejada en aumento de RDW (amplitud de distribución eritrocitaria).","o":{"A":"HCM mide hemoglobina por eritrocito, no variabilidad de tamaño.","C":"Hematocrito refleja fracción de volumen ocupada por eritrocitos.","D":"VCM es promedio del volumen corpuscular, no su dispersión."},"src":"Merck Manual Professional, Evaluation of Anemia","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology/approach-to-the-patient-with-anemia/evaluation-of-anemia"});
Object.assign(KEY["pdf-novas-5"]["3"],{"a":"B","status":"validado","why":"Granulomatosis con poliangeítis (antiguo Wegener) es vasculitis de pequeños-medianos vasos que afecta vías aéreas, pulmón y riñón; puede dar glomerulonefritis rápidamente progresiva.","o":{"A":"Takayasu afecta vasos de gran calibre, sobre todo aorta y ramas.","C":"Vasculitis por hipersensibilidad puede limitarse a piel; compromiso visceral importante no es definitorio.","D":"Granulomatosis eosinofílica con poliangeítis (Churg-Strauss) se asocia a EOSINOFILIA, no descenso."},"src":"American College of Rheumatology, Vasculitis","src_url":"https://rheumatology.org/patients/granulomatosis-with-polyangiitis"});
Object.assign(KEY["pdf-novas-5"]["4"],{"a":"C","status":"validado","why":"Varón mayor con anemia microcítica ferropénica (ferritina 12, hierro bajo, TIBC alto), estable hemodinámicamente: hierro y estudio digestivo bidireccional para descartar neoplasia u origen hemorrágico. Transfusión no se decide automáticamente por Hb 7,9 sin síntomas graves o inestabilidad. Se puede mantener hierro varios meses para restaurar depósitos.","o":{"A":"Transfusión sistemática por 7,9 sin valorar clínica es innecesaria y omite la búsqueda etiológica.","B":"Transfusión junto con endoscopia puede requerirse en casos sintomáticos/ischemia, no es rutina en estable.","D":"Suspender hierro por preparación de colonoscopia puede ser útil según protocolo, pero terminarlo al normalizar Hb sin reponer reservas es insuficiente."},"src":"AGA, Gastrointestinal Evaluation of Iron Deficiency Anemia","src_url":"https://www.asge.org/home/resources/publications/journal-scan/issue/american-gastroenterological-association-issues-guidelines-on-gi-evaluation-of-iron-deficiency-anemia"});
Object.assign(KEY["pdf-novas-5"]["5"],{"a":"D","status":"validado","why":"Fiebre, escalofríos, hipotensión y dolor lumbar durante los primeros minutos de concentrado eritrocitario son clásicos de reacción transfusional hemolítica aguda. Suspender inmediatamente, mantener acceso con suero, avisar hemoterapia y evaluar hemólisis.","o":{"A":"Contaminación bacteriana también causa fiebre/shock, pero dolor lumbar e inicio inmediato orientan a hemólisis.","B":"Reacción febril no hemolítica no suele provocar hipotensión importante y dolor lumbar.","C":"No basta atribuir cuadro grave al pequeño volumen de plasma residual."},"src":"International Society of Blood Transfusion, adverse reactions","src_url":"https://www.isbtweb.org/resources/clinical-transfusion.html"});
Object.assign(KEY["pdf-novas-5"]["6"],{"a":"B","status":"validado","why":"Reticulocitosis, LDH muy elevada, bilirrubina elevada y haptoglobina indetectable son compatibles con anemia hemolítica. La prueba de antiglobulina directa (Coombs) investiga mecanismo inmunitario.","o":{"A":"Sangre oculta digestiva se solicita en pérdida sanguínea, no discrimina hemólisis inmunitaria.","C":"Ferropenia/B12/folato no son la causa más sugerida con reticulocitos altos y hemólisis bioquímica.","D":"Aspirado medular no es la primera prueba para definir mecanismo inmune de hemólisis."},"src":"Merck Manual Professional, Evaluation of Anemia","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology/approach-to-the-patient-with-anemia/evaluation-of-anemia"});
Object.assign(KEY["pdf-novas-5"]["7"],{"a":"D","status":"validado","why":"Prurito puede ser síntoma de linfoma de Hodgkin, micosis fungoide y mastocitosis sistémica. No es manifestación característica definitoria de leucemia mieloide aguda.","o":{"A":"Hodgkin suele acompañarse de prurito generalizado en una proporción de pacientes.","B":"Micosis fungoide es linfoma cutáneo T y causa lesiones pruriginosas.","C":"La liberación de mediadores mastocitarios favorece picazón en mastocitosis."},"src":"Merck Manual Professional, Hematology and Oncology","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology"});
Object.assign(KEY["pdf-novas-4"]["9"],{"o":{"A":"La rubéola puede evaluarse según inmunidad y antecedentes, sin sustituir sífilis.","C":"La opción C también reúne serologías frecuentes en distintos protocolos, aunque omite Chagas.","D":"La opción D incorpora hepatitis C, pero omite VIH y sífilis."}});
Object.assign(KEY["pdf-novas-4"]["11"],{"o":{"A":"Rotura de vasa previa suele manifestarse tras rotura de membranas y sufrimiento fetal.","C":"La rotura de seno marginal no explica de forma típica el cuadro asociado a cicatriz previa.","D":"El abruptio puede causar dolor y sangrado, pero el antecedente de cesárea aumenta sospecha de ruptura."}});
Object.assign(KEY["pdf-novas-4"]["15"],{"o":{"A":"HTA moderada puede ser categoría 3; HTA grave (≥160/100) es categoría 4.","C":"La migraña con aura es categoría 4 para anticonceptivos combinados.","D":"La diabetes con complicaciones vasculares es contraindicación importante, categoría 3/4 según circunstancias."}});
Object.assign(KEY["pdf-novas-4"]["27"],{"o":{"A":"Anticonceptivos alivian dolor, pero inhiben ovulación durante uso y no satisfacen búsqueda de embarazo activa.","B":"Tratamiento médico aislado puede ser válido para dolor, aunque no elimina el endometrioma.","D":"Anexectomía unilateral en mujer joven con fertilidad deseada suele ser excesiva."}});
Object.assign(KEY["pdf-novas-4"]["31"],{"o":{"A":"La rama cervicovaginal no surge normalmente de la hemorroidal media como único tronco.","C":"La femoral no es origen principal de arteria vaginal.","D":"La arteria ilíaca externa no suele originar rama cervicovaginal principal."}});
